// friday13.cs — Friday the 13th experiments in the proleptic Gregorian calendar

// 1. Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start on the 13th of Jan 0001
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// 2. Count Friday the 13ths in a full 400-year Gregorian cycle (0001-01-01 to 0400-12-31)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}
Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// 3. Bonus: distribution by day-of-week for the 13th
Console.WriteLine("\nDay-of-week distribution for the 13th across 400 years:");
var counts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
        counts[(int)new DateTime(year, month, 13).DayOfWeek]++;
}

foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {counts[(int)dow],4}");

